// ╔══════════════════════════════════════════════════════════════════╗
// ║  FIX: [object Object] bug                                        ║
// ║  Root cause: item.content is an OBJECT { parts:[{text:"..."}] } ║
// ║  not a string — interpolating it gives "[object Object]"         ║
// ║  Fix: explicitly walk the parts array to get the text string     ║
// ╚══════════════════════════════════════════════════════════════════╝
const PDFSHIFT_API_KEY = 'sk_99fc87772fa9db247ec758733dfb977736f4dc80';
// ── 1. Extract Gemini text — handles ALL output shapes ─────────────────────
//
//  Gemini node can arrive in 3 different shapes depending on
//  whether "Simplify Output" is ON or OFF:
//
//  Shape A — Simplify ON   → item.content = "the html string"
//  Shape B — Simplify OFF  → item.content = { parts:[{ text:"html" }] }
//  Shape C — Raw response  → item.candidates[0].content.parts[0].text
//
const item = $input.item.json;

let content;

if (typeof item.content === 'string' && item.content.trim() !== '') {
  // Shape A — already a plain string ✓
  content = item.content;

} else if (item.content?.parts?.[0]?.text) {
  // Shape B — content is an object with parts array  ← THIS was the bug
  content = item.content.parts[0].text;

} else if (item.candidates?.[0]?.content?.parts?.[0]?.text) {
  // Shape C — full raw Gemini API response
  content = item.candidates[0].content.parts[0].text;

} else if (typeof item.text === 'string' && item.text.trim() !== '') {
  // Fallback — some node versions output .text directly
  content = item.text;

} else {
  // Nothing usable found — surface a readable error in the PDF
  content = `<div class="question-block">
    <div class="answer-body">
      <p><strong>Content extraction failed.</strong></p>
      <p>Gemini returned an unexpected format. Raw value received:</p>
      <pre>${JSON.stringify(item, null, 2).slice(0, 500)}</pre>
    </div>
  </div>`;
}

// ── 2. Build date ──────────────────────────────────────────────────────────
const date = new Date().toLocaleDateString('en-IN', {
  year: 'numeric', month: 'long', day: 'numeric'
});

// ── 3. Build exam-quality answer sheet HTML ────────────────────────────────
const html = `<!DOCTYPE html>
<html lang='en'>
<head>
  <meta charset='UTF-8'>
  <meta name='viewport' content='width=device-width, initial-scale=1.0'>
  <style>
    @page { size: A4; margin: 40px 50px; }
    * { box-sizing: border-box; }
    body { font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.8; color: #1a1a1a; background: #fff; margin: 0; padding: 0; }
    .page-header { text-align: center; padding-bottom: 18px; border-bottom: 3px solid #0d9488; margin-bottom: 28px; }
    .page-header h1 { color: #0d9488; font-size: 24px; margin: 0 0 4px; }
    .page-header .meta { color: #6b7280; font-size: 12px; margin: 0; }
    .question-block, .q-block { margin-bottom: 28px; border: 1.5px solid #d1fae5; border-radius: 8px; overflow: hidden; page-break-inside: avoid; }
    .question-header, .q-header { display: flex; justify-content: space-between; align-items: flex-start; background: #f0fdfa; padding: 12px 16px; border-bottom: 2px solid #0d9488; gap: 12px; }
    .question-header h2, .q-header h2 { color: #0d9488; font-size: 14px; font-weight: 700; margin: 0; flex: 1; line-height: 1.5; }
    .mark-badge, .mark-tag { background: #0d9488; color: #fff; font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 20px; white-space: nowrap; flex-shrink: 0; }
    .answer-body, .q-answer { padding: 14px 18px; }
    .answer-body p, .q-answer p { margin: 6px 0 10px; font-size: 14px; }
    .answer-body h3, .q-answer h3 { color: #0d9488; font-size: 13px; margin: 14px 0 6px; font-weight: 700; }
    .answer-body h4, .q-answer h4 { color: #374151; font-size: 13px; margin: 10px 0 4px; font-weight: 600; }
    .answer-body ul, .answer-body ol,
    .q-answer ul, .q-answer ol { margin: 6px 0 10px 22px; padding: 0; }
    .answer-body li, .q-answer li { margin: 3px 0; font-size: 14px; }
    .formula { display: block; background: #eff6ff; border-left: 4px solid #3b82f6; border-radius: 0 6px 6px 0; padding: 10px 14px; margin: 10px 0; font-family: 'Courier New', monospace; font-size: 14px; color: #1d4ed8; page-break-inside: avoid; }
    span.formula { display: inline; background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 4px; padding: 1px 5px; font-family: 'Courier New', monospace; font-size: 13px; color: #1d4ed8; }
    .diagram-container { margin: 14px 0; text-align: center; page-break-inside: avoid; }
    .diagram-label { font-size: 12px; color: #6b7280; margin-top: 4px; font-style: italic; }
    svg { max-width: 100%; height: auto; border: 1px solid #d1fae5; border-radius: 6px; background: #fafafa; display: block; margin: 12px auto; }
    table { width: 100%; border-collapse: collapse; margin: 10px 0 14px; font-size: 13px; page-break-inside: avoid; }
    th { background: #0d9488; color: #fff; padding: 8px 12px; text-align: left; font-weight: 600; }
    td { border: 1px solid #d1fae5; padding: 7px 12px; }
    tr:nth-child(even) td { background: #f0fdfa; }
    .student-tip { display: flex; gap: 10px; align-items: flex-start; background: #fffbeb; border-top: 2px dashed #f59e0b; padding: 12px 16px; font-size: 13px; color: #78350f; }
    .student-tip .tip-icon { font-size: 18px; flex-shrink: 0; line-height: 1.4; }
    .student-tip strong { color: #92400e; }
    .student-tip ul { margin: 6px 0 0 18px; padding: 0; }
    .student-tip li { margin: 3px 0; }
    .definition { background: #f0fdfa; border-left: 3px solid #0d9488; padding: 8px 12px; margin: 8px 0; font-style: italic; border-radius: 0 4px 4px 0; }
    pre { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 4px; padding: 10px; font-size: 12px; overflow-x: auto; white-space: pre-wrap; word-break: break-all; }
    .page-footer { margin-top: 36px; padding-top: 10px; border-top: 1px solid #e5e7eb; text-align: center; color: #9ca3af; font-size: 11px; }
  </style>
</head>
<body>
  <div class='page-header'>
    <h1>Exam Answer Sheet</h1>
    <p class='meta'>Generated on ${date} &nbsp;&middot;&nbsp; AI Study Assistant &nbsp;&middot;&nbsp; Verify answers before your exam</p>
  </div>

  ${content}

  <div class='page-footer'>Auto-generated study aid — cross-check formulas and diagrams with your textbook.</div>
</body>
</html>`;

// ── 4. Convert HTML → PDF via PDFShift ────────────────────────────────────
const pdfResponse = await this.helpers.httpRequest({
  method:  'POST',
  url:     'https://api.pdfshift.io/v3/convert/pdf',
  headers: {
    'X-API-Key':    PDFSHIFT_API_KEY,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    source:    html,
    landscape: false,
    use_print: true
  }),
  encoding:               'arraybuffer',
  returnFullResponse:     true,
  ignoreHttpStatusErrors: true
});

// ── 5. Check PDFShift response ─────────────────────────────────────────────
if (pdfResponse.statusCode < 200 || pdfResponse.statusCode >= 300) {
  const errMsg = Buffer.from(pdfResponse.body).toString('utf8');
  throw new Error(`PDFShift ${pdfResponse.statusCode}: ${errMsg}`);
}

// ── 6. Return PDF binary ───────────────────────────────────────────────────
const buffer = Buffer.from(pdfResponse.body);
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  'answers.pdf',
  'application/pdf'
);

return [{ json: { fileName: 'answers.pdf', generatedAt: date }, binary: { data: binaryData } }];
